import React from 'react';

export function Button({ 
  children, 
  href, 
  onClick, 
  className = "" 
}: { 
  children: React.ReactNode, 
  href?: string, 
  onClick?: () => void,
  className?: string 
}) {
  const baseClasses = "inline-flex items-center justify-center px-6 py-3 font-display font-medium text-sm tracking-tight transition-colors duration-200 text-canvas bg-ink hover:bg-signal rounded-full cursor-pointer";
  
  if (href) {
    return (
      <a href={href} className={`${baseClasses} ${className}`}>
        {children}
      </a>
    );
  }
  
  return (
    <button onClick={onClick} className={`${baseClasses} ${className}`}>
      {children}
    </button>
  );
}

export function Tag({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-block px-2 py-1 text-xs font-mono tracking-wider uppercase text-slate border border-hairline rounded">
      {children}
    </span>
  );
}

export function SectionHeading({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="font-display text-4xl md:text-5xl lg:text-6xl tracking-tight text-ink mb-12">
      {children}
    </h2>
  );
}

export function Divider() {
  return <div className="w-full h-px bg-hairline my-16" />;
}
