import { projects } from '@/data/projects';
import { notFound } from 'next/navigation';
import { Divider, Tag } from '@/components/ui';
import Link from 'next/link';

export function generateStaticParams() {
  return projects.map((project) => ({
    slug: project.slug,
  }));
}

export default async function CaseStudy({ params }: { params: Promise<{ slug: string }> }) {
  const resolvedParams = await params;
  const project = projects.find(p => p.slug === resolvedParams.slug);

  if (!project) {
    notFound();
  }

  const nextProjectIndex = projects.findIndex(p => p.slug === resolvedParams.slug) + 1;
  const nextProject = projects[nextProjectIndex] || projects[0];

  return (
    <main className="min-h-screen pt-48 pb-32">
      {/* Header */}
      <header className="px-6 md:px-12 max-w-5xl mx-auto mb-16">
        <h1 className="font-display text-5xl md:text-7xl font-medium tracking-tight text-ink mb-6">{project.title}</h1>
        <div className="flex flex-wrap gap-4 font-mono text-sm text-slate uppercase tracking-widest">
          <span>Client: {project.client}</span>
          <span>&times;</span>
          <span>{project.year}</span>
        </div>
      </header>

      {/* Hero Media */}
      <div className="w-full h-[70vh] bg-slate/10 mb-24 relative overflow-hidden">
        {project.heroMedia.src ? (
          <img src={project.heroMedia.src} alt={project.heroMedia.alt} className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex items-center justify-center font-mono text-slate text-sm">MEDIA_AWAITING_INGESTION</div>
        )}
      </div>

      <div className="px-6 md:px-12 max-w-4xl mx-auto flex flex-col gap-24">
        {/* Overview */}
        <section>
          <Tag>OVERVIEW</Tag>
          <p className="font-sans text-xl md:text-3xl text-ink leading-snug mt-6">{project.overview}</p>
        </section>

        {/* The Challenge */}
        <section>
          <Tag>THE CHALLENGE</Tag>
          <p className="font-sans text-lg text-slate leading-relaxed mt-6">{project.challenge}</p>
        </section>

        {/* The Approach */}
        <section>
          <Tag>THE APPROACH</Tag>
          <p className="font-sans text-lg text-slate leading-relaxed mt-6">{project.approach}</p>
        </section>

        {/* Tech & Services */}
        <section className="grid grid-cols-1 md:grid-cols-2 gap-12 pt-12 border-t border-hairline">
          <div>
            <h4 className="font-mono text-sm uppercase tracking-widest text-slate mb-4">Technologies</h4>
            <ul className="flex flex-wrap gap-2">
              {project.technologies.map(tech => <li key={tech} className="font-sans text-ink bg-canvas border border-hairline px-3 py-1 rounded-full text-sm">{tech}</li>)}
            </ul>
          </div>
          <div>
            <h4 className="font-mono text-sm uppercase tracking-widest text-slate mb-4">Services</h4>
            <ul className="flex flex-wrap gap-2">
              {project.services.map(service => <li key={service} className="font-sans text-ink bg-canvas border border-hairline px-3 py-1 rounded-full text-sm">{service}</li>)}
            </ul>
          </div>
        </section>

        {/* Results */}
        {project.result && (
          <section className="bg-ink text-canvas p-12 rounded-xl">
            <Tag>RESULT</Tag>
            <p className="font-sans text-2xl leading-snug mt-6">{project.result}</p>
          </section>
        )}
      </div>

      <Divider />

      <section className="px-6 md:px-12 max-w-4xl mx-auto flex justify-between items-center">
        <span className="font-mono text-sm uppercase tracking-widest text-slate">Next Project</span>
        <Link href={`/work/${nextProject.slug}`} className="font-display text-4xl hover:text-signal transition-colors">
          {nextProject.title} &rarr;
        </Link>
      </section>
    </main>
  );
}
